import { useMemo, useState } from 'react';
import {
  JxBadge,
  JxButton,
  JxChip,
  JxDivider,
  JxEmptyState,
  JxPagination,
  JxProgressCircle,
} from '@jinx-ui/react';

type ProjectStatus = 'active' | 'paused' | 'over';

type Project = {
  id: string;
  name: string;
  quota: number;
  status: ProjectStatus;
};

const PAGE_SIZE = 5;

const STATUS_META: Record<ProjectStatus, { label: string; tone: 'success' | 'warning' | 'danger' }> = {
  active: { label: 'Активен', tone: 'success' },
  paused: { label: 'На паузе', tone: 'warning' },
  over: { label: 'Превышение', tone: 'danger' },
};

const ALL_STATUSES: ProjectStatus[] = ['active', 'paused', 'over'];

const PROJECTS: Project[] = [
  { id: 'p1', name: 'Контекстная лаборатория', quota: 72, status: 'active' },
  { id: 'p2', name: 'Пайплайн импорта', quota: 41, status: 'paused' },
  { id: 'p3', name: 'Поисковый индекс', quota: 98, status: 'over' },
  { id: 'p4', name: 'Мобильный клиент', quota: 55, status: 'active' },
  { id: 'p5', name: 'Биллинг', quota: 12, status: 'paused' },
  { id: 'p6', name: 'Аналитика событий', quota: 87, status: 'active' },
  { id: 'p7', name: 'Экспорт отчётов', quota: 100, status: 'over' },
  { id: 'p8', name: 'Интеграции', quota: 34, status: 'active' },
  { id: 'p9', name: 'Документация', quota: 8, status: 'paused' },
  { id: 'p10', name: 'Онбординг', quota: 63, status: 'active' },
  { id: 'p11', name: 'Уведомления', quota: 91, status: 'over' },
];

export default function ProjectSpendPanel() {
  const [statuses, setStatuses] = useState<ProjectStatus[]>(ALL_STATUSES);
  const [page, setPage] = useState(1);

  const visible = useMemo(
    () => PROJECTS.filter((project) => statuses.includes(project.status)),
    [statuses],
  );

  const pageCount = Math.max(1, Math.ceil(visible.length / PAGE_SIZE));
  const safePage = Math.min(page, pageCount);
  const rows = visible.slice((safePage - 1) * PAGE_SIZE, safePage * PAGE_SIZE);

  const removeStatus = (status: ProjectStatus) => {
    setStatuses((current) => current.filter((item) => item !== status));
    setPage(1);
  };

  const resetFilters = () => {
    setStatuses(ALL_STATUSES);
    setPage(1);
  };

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '16px',
        padding: '20px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', alignItems: 'center' }}>
        {statuses.length === 0 ? (
          <span style={{ color: 'var(--jx-text-3)', fontSize: '13px' }}>Все фильтры сняты</span>
        ) : (
          statuses.map((status) => (
            <JxChip key={status} active removable onRemove={() => removeStatus(status)}>
              {STATUS_META[status].label}
            </JxChip>
          ))
        )}
      </div>

      <JxDivider />

      {rows.length === 0 ? (
        <JxEmptyState
          title="Ничего не найдено"
          message="Под выбранные фильтры не попал ни один проект."
          action={
            <JxButton variant="primary" onClick={resetFilters}>
              Сбросить фильтры
            </JxButton>
          }
        />
      ) : (
        <>
          <ul style={{ listStyle: 'none', margin: 0, padding: 0, display: 'flex', flexDirection: 'column', gap: '8px' }}>
            {rows.map((project) => (
              <li
                key={project.id}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '16px',
                  padding: '12px 14px',
                  background: 'var(--jx-surface-2)',
                  border: '1px solid var(--jx-border)',
                  borderRadius: 'var(--jx-r)',
                }}
              >
                <JxProgressCircle value={project.quota} showValue />
                <span style={{ flex: 1, minWidth: 0, color: 'var(--jx-text)' }}>{project.name}</span>
                <JxBadge tone={STATUS_META[project.status].tone} dot>
                  {STATUS_META[project.status].label}
                </JxBadge>
              </li>
            ))}
          </ul>

          <JxPagination total={pageCount} page={safePage} onPageChange={setPage} />
        </>
      )}
    </section>
  );
}

